/* ---------- scoring ---------- */
function needMet(c,subs){return c.need.map(function(n){return{n:n,ok:n.split('|').some(function(k){return subs.indexOf(k)>-1})}});}
function helps(c,k){return c.help.indexOf(k)>-1||(SUBJ_AREAS[k]||[]).indexOf(c.area)>-1;}
function score(c,subs){
 var nm=needMet(c,subs),ok=nm.filter(function(x){return x.ok}).length,miss=nm.length-ok;
 var hh=Math.min(3,subs.reduce(function(t,k){var i=c.help.indexOf(k);return t+(i===0?1.4:i===1?1.2:i>1?1:(SUBJ_AREAS[k]||[]).indexOf(c.area)>-1?.6:0)},0));
 var pct=subs.length?Math.round(Math.min(1,(ok*2+hh)/(nm.length*2+2.5))*100):0;
 if(nm.length&&!miss)pct=Math.min(98,pct+15);if(miss)pct=Math.min(pct,40);pct=Math.min(pct,98);
 return{pct:pct,miss:miss,nm:nm};}
function gcAreas(){var g=PF.gc,a=[];[g.arts,g.hum,g.lang,g.open].forEach(function(s){if(s&&GINFO[s])a=a.concat(GINFO[s][2]);});if(g.sci==='trip')a=a.concat(GSCI.trip[2]);return a;}
function intAreas(){var s=[];PF.int.forEach(function(i){var x=INTERESTS.filter(function(y){return y[0]===i})[0];if(x)s=s.concat(x[2]);});return s;}
function areaRank(){
 var fi=intAreas(),ga=PF.stage==='gcse'?gcAreas():[],useS=PF.stage==='college'&&PF.subj.length;
 return AORD.map(function(a){
  var cs=CAR.filter(function(c){return c.area===a});var s=0;
  if(useS){var p=cs.map(function(c){return score(c,PF.subj).pct});s=Math.max.apply(null,p)*.6+p.reduce(function(x,y){return x+y},0)/p.length*.4;}
  if(fi.indexOf(a)>-1)s+=useS?18:60;
  ga.forEach(function(x){if(x===a)s+=22;});
  return{a:a,s:Math.round(s),n:cs.length};}).sort(function(x,y){return y.s-x.s||AORD.indexOf(x.a)-AORD.indexOf(y.a)});}
function suggestSubj(){var ar=intAreas(),sc={};CAR.forEach(function(c){if(ar.indexOf(c.area)<0)return;c.need.forEach(function(n){n.split('|').forEach(function(k){sc[k]=(sc[k]||0)+3})});c.help.forEach(function(k){sc[k]=(sc[k]||0)+1});});return Object.keys(sc).filter(function(k){return SUBJ_KEYS[k]}).sort(function(a,b){return sc[b]-sc[a]}).slice(0,8);}
function noDeg(c){return /^Not needed/.test(c.deg);}
function noAppr(c){return /^No (apprenticeship|formal|set)/i.test(c.appr);}

/* ---------- navigation ---------- */
function go(step,keep){if(!keep)PF.hist.push(PF.step);PF.step=step;save();draw();try{scrollTo({top:0,behavior:'auto'})}catch(e){scrollTo(0,0)}}
function back(){var s=PF.hist.pop();PF.step=s||'start';save();draw();scrollTo(0,0);}
function reset(){PF=fresh();save();draw();scrollTo(0,0);}
var FLOW={gcse:['start','int','gcse','areas','careers','career'],yr11:['start','grades','routes','int','areas','careers','career'],college:['start','cmode','int','subj','areas','careers','career'],adult:['start','int','areas','careers','career'],unsure:['start','int','areas','careers','career']};
function prog(){var f=FLOW[PF.stage]||['start'];var i=f.indexOf(PF.step);if(PF.stage==='college'&&PF.mode==='know'){f=f.filter(function(x){return x!=='int'});i=f.indexOf(PF.step);}return i<0?0:i/(f.length-1);}

/* ---------- pieces ---------- */
function top(){
 if(PF.step==='start')return '';
 return '<div class="pth-bar"><button type="button" class="pth-ib" data-p="back" aria-label="Back">'+IC.back+'</button><div class="pth-prog"><i style="width:'+Math.max(6,prog()*100)+'%"></i></div><button type="button" class="pth-reset" data-p="reset">'+IC.reset+'<span>Start again</span></button></div>';}
function head(t,sub){return '<div class="pth-h"><h2>'+t+'</h2>'+(sub?'<p>'+sub+'</p>':'')+'</div>';}
function cta(label,act,dis,extra){return '<div class="pth-cta"><div class="pth-cta-in">'+(extra||'')+'<button type="button" class="pth-go" data-p="'+act+'"'+(dis?' disabled':'')+'><span>'+label+'</span>'+IC.next+'</button></div></div>';}
function sel(id,label,opts,val,sug){return '<label class="pth-sel"><span>'+label+'</span><span class="pth-sw"><select data-g="'+id+'"><option value="">Choose one</option>'+opts.map(function(o){return '<option'+(o===val?' selected':'')+' value="'+esc(o)+'">'+esc(o)+(sug&&sug.indexOf(o)>-1?'  (suggested)':'')+'</option>'}).join('')+'</select></span></label>';}
function gsel(k,v){var h='<select data-gr="'+k+'">';for(var g=9;g>=1;g--)h+='<option'+(g==v?' selected':'')+'>'+g+'</option>';return h+'</select>';}

