 var sub=PF.stage==='college'&&PF.subj.length?'With '+PF.subj.map(function(k){return SUBJ_KEYS[k]}).join(', ')+'. Tap an area to see the careers.':'Best matches first. Tap an area to see the careers.';
 return head('Where you could go',sub)+'<div class="pth-areas">'+r.map(function(x,i){var A=AREAS[x.a];var ex=CAR.filter(function(c){return c.area===x.a}).slice(0,3).map(function(c){return c.n}).join(', ');return '<button type="button" class="pth-area'+(i<topN?' top':'')+'" data-p="area" data-v="'+x.a+'"><i>'+AI[x.a]+'</i><span class="pth-at"><span class="pth-an"><b>'+esc(A[0])+'</b>'+(i<topN?'<em>'+(i===0?'Best match':'Good match')+'</em>':'')+'</span><small>'+esc(ex)+'</small></span><span class="pth-n">'+x.n+'</span>'+IC.next+'</button>'}).join('')+'</div>'
