 return head(R.length>2?'You could get help with '+R.length+' things':'Here’s what you could get','A guide only. Your college checks what you can get.')+'<div class="pth-mr">'+R.map(function(x){return '<div class="pth-mc"><span>'+esc(x[0])+'</span><div><b>'+esc(x[1])+'</b><p>'+esc(x[2])+'</p></div></div>'}).join('')+'</div>'
