function draw(){if(!root)return;root.innerHTML=top()+'<div class="pth-body s-'+PF.step+'">'+(V[PF.step]||V.start)()+'</div>';var q=root.querySelector('#pthQ');if(q)q.addEventListener('input',filt);}
function filt(){var q=(this.value||'').toLowerCase();root.querySelectorAll('.pth-sb').forEach(function(b){b.style.display=!q||b.textContent.toLowerCase().indexOf(q)>-1?'':'none'});}
function onClick(e){
 var b=e.target.closest('[data-p]');if(!b||!root.contains(b))return;var a=b.dataset.p,v=b.dataset.v;
 if(a==='back')return back();
 if(a==='reset'){if(PF.step==='start')return;return reset();}
 if(a==='stage'){var keep=PF.ch;PF=fresh();PF.ch=keep;PF.stage=v;PF.hist=['start'];PF.step=v==='yr11'?'grades':v==='college'?'cmode':'int';save();draw();scrollTo(0,0);return;}
 if(a==='resume'){PF.hist=['start'];return go('career',true);}
 if(a==='money'){PF.ch={i:0,a:[]};return go('money');}
 if(a==='routes1')return go('routes1');
 if(a==='int'){var i=PF.int.indexOf(v);i<0?PF.int.push(v):PF.int.splice(i,1);save();var y=scrollY;draw();scrollTo(0,y);return;}
 if(a==='afterInt')return go(PF.stage==='gcse'?'gcse':PF.stage==='college'?'subj':'areas');
 if(a==='cmode'){PF.mode=v;return go(v==='know'?'subj':'int');}
 if(a==='subj'){var j=PF.subj.indexOf(v);if(j<0){if(PF.subj.length>=4){toast('You can pick up to 4. Remove one first.');return;}PF.subj.push(v);}else PF.subj.splice(j,1);save();var qv=(root.querySelector('#pthQ')||{}).value,y2=scrollY;draw();if(qv){var q=root.querySelector('#pthQ');q.value=qv;filt.call(q);}scrollTo(0,y2);return;}
 if(a==='sci'){PF.gc.sci=v;save();var y3=scrollY;draw();scrollTo(0,y3);return;}
 if(a==='toAreas')return go('areas');
 if(a==='toRoutes')return go('routes');
 if(a==='toInt')return go('int');
 if(a==='editSubj')return go('subj');
 if(a==='area'){PF.area=v;return go('careers');}
 if(a==='career'){PF.career=v;PF.area=(CAR.filter(function(c){return c.id===v})[0]||{}).area||PF.area;return go('career');}
 if(a==='addg'){PF.gr.o.push(['',5]);save();var y4=scrollY;draw();scrollTo(0,y4);return;}
 if(a==='rmg'){PF.gr.o.splice(+v,1);save();var y5=scrollY;draw();scrollTo(0,y5);return;}
 if(a==='ans'){PF.ch.a[PF.ch.i]=v;PF.ch.i++;if(PF.ch.i===1&&v==='19 or over'){PF.ch.a[1]=PF.ch.a[2]=PF.ch.a[3]='No';PF.ch.i=4;}save();draw();scrollTo(0,0);return;}
 if(a==='chreset'){PF.ch={i:0,a:[]};save();draw();scrollTo(0,0);return;}
 if(a==='share')return share();}
function onChange(e){var t=e.target;
 if(t.dataset.g){PF.gc[t.dataset.g]=t.value;save();var y=scrollY;draw();scrollTo(0,y);return;}
 if(t.dataset.gr){var k=t.dataset.gr;if(k[0]==='o')PF.gr.o[+k.slice(1)][1]=+t.value;else PF.gr[k]=+t.value;save();var r=root.querySelector('#pthGres');if(r)r.innerHTML=gres();return;}
 if(t.dataset.on!=null){PF.gr.o[+t.dataset.on][0]=t.value;save();}}
function toast(m){var t=document.createElement('div');t.className='pth-toast';t.textContent=m;document.body.appendChild(t);setTimeout(function(){t.classList.add('in')},10);setTimeout(function(){t.remove()},2600);}
function share(){var c=CAR.filter(function(x){return x.id===PF.career})[0];if(!c)return;var X=AX[c.area];
 var t='My path: '+c.n+'\n'+(PF.subj.length?'Subjects: '+PF.subj.map(function(k){return SUBJ_KEYS[k]}).join(', ')+'\n':'')+'Useful GCSEs: '+X.g+'\nAfter 16: '+X.p+'\nUniversity route: '+c.deg+'\nApprenticeship route: '+c.appr+'\n\nMade with Pathfinder on My Sirat';
 if(navigator.share){navigator.share({title:'My path: '+c.n,text:t}).catch(function(){});return;}
 try{navigator.clipboard.writeText(t).then(function(){toast('Copied. Paste it to a parent, teacher or friend.')},function(){toast('Couldn’t copy here.')});}catch(e){toast('Couldn’t copy here.');}}
function init(){root=document.getElementById('pthRoot');if(!root||root.dataset.on)return;root.dataset.on=1;root.addEventListener('click',onClick);root.addEventListener('change',onChange);draw();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
window.NGSPathfinder={reset:reset,draw:draw};

